effect.shader:
/** O ruído do Scatter, com o hash inteiro do plugin (0x45d9f3b) e o resto em C. */
float ruido(int x, int y, float semente) {
    uint s = uint(int(semente));
    uint h = uint(y) * uint(y) + s + uint(x);
    h = ((h >> 16u) ^ h) * 0x45d9f3bu;
    h = ((h >> 16u) ^ h) * 0x45d9f3bu;
    h = (h >> 16u) ^ h;
    // h % 512 com o sinal de int32 (truncado para zero, como em C).
    bool negativo = (h >> 31u) != 0u;
    uint modulo = (negativo ? (~h + 1u) : h) & 511u;
    int r = negativo ? -int(modulo) : int(modulo);
    return float(r - 256);
}

void main() {
    vec4 fonte = texture(inputImg, acScreenNorm);
    float esc = max(acEscalaDePixel, 1e-4);
    ivec2 p = ivec2(floor(acScreenNorm * acResolution));
    vec2 c = center * acResolution;
    float d = length(vec2(p) - c);
    float R = radius * esc;
    float F = feather * esc;
    float ex = expansion / 100.0;

    float v = -2.0;
    if (R > d) {
        if (ex > 0.0) v = d / (ex * R) + 1.0 - 1.0 / ex;
    } else if (F > 0.0) {
        v = 1.0 - (d - R) / F;
    }
    if (scatter > 0.0) {
        v += ruido(p.x, p.y, scatter * scatter * 256.0) * scatter * 1e-6;
    }
    v = clamp(v, 0.0, 1.0);
    if (suave) v = (1.0 - cos(v * 3.14159265359)) * 0.5;
    float m = v * (opacity / 100.0);
    vec3 cor = color2.rgb + (color1.rgb - color2.rgb) * m;

    float A = fonte.a;
    vec4 o;
    if (blend == 0) {
        o = vec4(cor, m);
    } else if (blend == 1 || blend == 2) {
        float a = 1.0 - (1.0 - m) * (1.0 - A);
        float k = a != 0.0 ? m / a : 0.0;
        vec3 rgb = blend == 1
            ? cor * k + fonte.rgb * (1.0 - k)
            : min(k * (cor + A * fonte.rgb) + (1.0 - k) * fonte.rgb, vec3(1.0));
        o = vec4(rgb, a);
    } else {
        vec3 t = fonte.rgb * A * cor * m;
        if (blend == 3) {
            o = vec4(t, 1.0);
        } else {
            float a = max(t.r, max(t.g, t.b));
            o = a > 0.0 ? vec4(t / a, a) : vec4(0.0);
        }
    }
    fragColor = o;
}
